  });

  it("startup=false 注册失败后 tools 保持旧引用", async () => {
    // 现状语义：startup=false 注册失败直接 return，tools/toolDisposers 保持旧引用
    // （旧 disposer 已执行，工具实际已注销；数组内容不再代表可用集合）。
    const { supFail } = await rollbackFixture();
