    expect(single.length <= 240).toBeTruthy();
  });

  it("极端长句带省略号", () => {
    const single = summarizeToolDescriptions(new Map([["x", { description: "长".repeat(500) }]]));
    expect(single.endsWith("…")).toBeTruthy();
  });
});

