          event(1),
          { type: "user/message", seq: 2, data: { source: { kind: "mcp-catalog", entries: "bad" } } },
        ],
      },
    };
    expect(catalogHistory(agentBadThenGood).visibleDigest).toEqual(digest);
  });

  it("只有非目录消息 → {published:false}", () => {
